balpost.com/dispatch/news/kyodo-news-international/140502/s-korea-court-rejects-suit-seeking-return-statue-japan |access-date=2023-11-20 |archive-url=https://web.archive.org/web/20150527150211/http://www.globalpost.com/dispatch/news/kyodo-news-international/140502/s-korea-court-rejects-suit-seeking-return-statue-japan |archive-date=2015-05-27 }}</ref><ref name="faure-2021a" />{{rp||pages=321}}

